-- Weekly Arena 2026-W51: generated by scripts/weekly-arena.ts. Safe to rerun (skips if the title already exists).
insert into public.arenas(title, description, starts_at, ends_at, duration_minutes, status, questions)
select 'Weekly Arena 2026-W51', 'Fresh weekly set of 10 numeric questions across Algebra, Geometry, Combinatorics and Number Theory. Each question allows three submissions. New questions every week, none repeated from earlier arenas.', '2026-12-14T00:00:00.000Z', '2026-12-21T00:00:00.000Z', 60, 'published', $WK5adbe9035134$[{"id":"wk-2026-w51-01-a8dc","title":"Triangles From Diagonals Only","topic":"Geometry","level":"Intermediate","question":"Three vertices of a convex $11$-gon are chosen so that none of the three sides of the resulting triangle is a side of the polygon. How many such triangles are there?","type":"text","correctAnswer":"77","hint":"Count all triangles and remove those that use at least one polygon side, by inclusion-exclusion.","solution":"The count is $\\dfrac{n(n-4)(n-5)}{6}$ with $n=11$, i.e. $77$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w51-02-f07e","title":"A Blocked Lattice Path","topic":"Combinatorics","level":"Intermediate","question":"A path from $(0,0)$ to $(7,9)$ moves only one unit right or one unit up at each step. How many such paths avoid the point $(1,7)$?","type":"text","correctAnswer":"11216","hint":"Subtract the paths that pass through the forbidden point from the total.","solution":"$\\binom{16}{7}-\\binom{8}{1}\\binom{8}{6}=11216$.","answerMode":"numeric-grid","answerDigits":5,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w51-03-7dce","title":"Coprime Count","topic":"Number Theory","level":"Intermediate","question":"How many integers $n$ with $1\\le n\\le 518$ are relatively prime to $30$?","type":"text","correctAnswer":"138","hint":"Remove multiples of 2, 3, 5 using inclusion-exclusion.","solution":"Inclusion-exclusion over the primes 2, 3, 5 leaves $138$ integers.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2026-w51-04-de5b","title":"Three Remainders","topic":"Number Theory","level":"Intermediate","question":"Find the smallest positive integer $n$ such that $n\\equiv 1 \\pmod{7}$, $n\\equiv 1 \\pmod{5}$, $n\\equiv 1 \\pmod{9}$.","type":"text","correctAnswer":"1","hint":"The moduli are pairwise coprime, so the Chinese Remainder Theorem gives a unique residue class.","solution":"Combining the congruences gives the residue class of $1$ modulo $315$, and $1$ is its smallest positive member.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w51-05-8075","title":"Reciprocal Powers","topic":"Algebra","level":"Intermediate","question":"A positive real number $x$ satisfies $x + \\dfrac{1}{x} = 5$. Find $x^{6} + \\dfrac{1}{x^{6}}$.","type":"text","correctAnswer":"12098","hint":"Set $T_m=x^m+x^{-m}$; then $T_m=5T_{m-1}-T_{m-2}$.","solution":"With $T_0=2$, $T_1=5$ the recurrence gives $T_{6}=12098$.","answerMode":"numeric-grid","answerDigits":5,"maxAttempts":3,"estimatedSteps":3,"abstraction":2,"points":47,"difficulty":-0.52},{"id":"wk-2026-w51-06-2c5f","title":"Tangent and Secant","topic":"Geometry","level":"Intermediate","question":"From an external point $P$, a tangent $PT$ of length $20$ and a secant meeting the circle at $A$ and $B$ are drawn, with $PA < PB$ and $PA=10$. Find $PA + PB + PT$.","type":"text","correctAnswer":"70","hint":"Apply the power of a point: $PT^2=PA\\cdot PB$.","solution":"$PB=20^2/10=40$, so the sum is $10+40+20=70$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":3,"abstraction":3,"points":53,"difficulty":-0.28},{"id":"wk-2026-w51-07-5015","title":"Powers of the Roots","topic":"Algebra","level":"Advanced","question":"Let $r$ and $s$ be the roots of $t^2 - 6t + 1 = 0$. Find the remainder when $r^{5} + s^{5}$ is divided by $1000$.","type":"text","correctAnswer":"726","hint":"Let $S_k=r^k+s^k$. Then $S_k=6S_{k-1}-1S_{k-2}$, with $S_0=2$, $S_1=6$.","solution":"Using $S_k=6S_{k-1}-1S_{k-2}$ from $S_0=2$, $S_1=6$ gives $S_{5}=6726$, whose remainder modulo $1000$ is $726$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w51-08-c7af","title":"A Floor Sum","topic":"Algebra","level":"Advanced","question":"Compute $\\displaystyle\\sum_{k=1}^{38} \\left\\lfloor \\frac{5k}{7} \\right\\rfloor$.","type":"text","correctAnswer":"513","hint":"Write $5k=7q+r$ and track how the remainder cycles with period $7$.","solution":"Evaluating each floor term and adding gives $513$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w51-09-fe78","title":"Lattice Points Inside","topic":"Geometry","level":"Advanced","question":"A triangle has vertices $(0,0)$, $(9,10)$ and $(8,4)$ in the coordinate plane. How many points with integer coordinates lie strictly inside the triangle?","type":"text","correctAnswer":"20","hint":"Use Pick's theorem: $A=I+B/2-1$, with $B$ counted by gcds along each side.","solution":"Twice the area is $44$ and the boundary has $B=6$ lattice points, so $I=(44-6+2)/2=20$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":4,"abstraction":3,"points":60,"difficulty":0},{"id":"wk-2026-w51-10-1dc7","title":"Rearranging a Word","topic":"Combinatorics","level":"Advanced","question":"In how many distinct ways can the letters of $\\text{TMDDDKKK}$ be rearranged so that no two identical letters are adjacent?","type":"text","correctAnswer":"184","hint":"Count all arrangements, then use inclusion-exclusion by gluing identical letters together.","solution":"Inclusion-exclusion (confirmed by exhaustive enumeration) gives $184$.","answerMode":"numeric-grid","answerDigits":3,"maxAttempts":3,"estimatedSteps":5,"abstraction":4,"points":73,"difficulty":0.52}]$WK5adbe9035134$::jsonb
